import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = data[1] if len(data) > 1 else ""
    n = len(s)
    left = [0] * n   # count of consecutive '1' ending at i-1
    for i in range(n):
        if i == 0:
            left[i] = 0
        else:
            left[i] = left[i-1] + 1 if s[i-1] == '1' else 0
    right = [0] * n  # count of consecutive '2' starting at i+1
    for i in range(n - 1, -1, -1):
        if i == n - 1:
            right[i] = 0
        else:
            right[i] = right[i+1] + 1 if s[i+1] == '2' else 0
    ans = 0
    for i in range(n):
        if s[i] == '/':
            v = 2 * min(left[i], right[i]) + 1
            if v > ans:
                ans = v
    print(ans)

