class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        total = 0
        for i, ch in enumerate(s):
            c = ord(ch) - 97
            m = 25 - c
            if stacks[m]:
                j = stacks[m].pop()
                total += i - j
            else:
                stacks[c].append(i)
        return total

from typing import List


class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [-1] * numberOfUsers

        # OFFLINE events (and returning online) are processed before MESSAGE
        # events at the same timestamp.
        ordered = sorted(
            events,
            key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1),
        )

        for typ, ts, data in ordered:
            t = int(ts)
            if typ == "OFFLINE":
                offline_until[int(data)] = t + 60
            else:
                for token in data.split():
                    if token == "ALL":
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif token == "HERE":
                        for i in range(numberOfUsers):
                            if offline_until[i] <= t:
                                mentions[i] += 1
                    elif token.startswith("id"):
                        idx = int(token[2:])
                        if 0 <= idx < numberOfUsers:
                            mentions[idx] += 1

        return mentions

