import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); q = int(data[1])
    NN = n * n
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for r in range(n + 1):
        row = dp[r]
        for c in range(n + 1):
            cur = row[c]
            if not cur:
                continue
            for a in range(2, n - r + 1):
                tgt = dp[r + a]
                for b in range(2, n - c + 1):
                    tgt[c + b] |= cur << (a * b)
    mask = 0
    for r in range(n + 1):
        for c in range(n + 1):
            mask |= dp[r][c]
    out = []
    for i in range(q):
        k = int(data[2 + i])
        s = NN - k
        out.append("Yes" if 0 <= s <= NN and (mask >> s) & 1 else "No")
    sys.stdout.write("\n".join(out) + "\n")

main()
